uint8_t* readFile(str_strView path, uint32_t* outLen)
{
    void* f = fopen(path.ptr, "rb");
    if ((f == NULL))
    {
        return NULL;
    }
    uint64_t cap = (uint64_t)((1u << 16));
    uint8_t* buf = mman_alloc_u8(cap);
    uint64_t used = 0;
    for (; ; )
    {
        uint64_t got = fread((buf + used), 1, (cap - used), f);
        (used += got);
        if ((got == 0))
        {
            break;
        }
        if ((used == cap))
        {
            uint64_t nc = (cap * 2);
            (buf = mman_realloc_u8(buf, nc));
            (cap = nc);
        }
    }
    fclose(f);
    ((*outLen) = (uint32_t)used);
    return buf;
}

bool vEqCI(str_strView a, str_strView b)
{
    if ((a.len != b.len))
    {
        return false;
    }
    for (uint32_t i = 0; (i < a.len); (i++))
    {
        char ca = a.ptr[i];
        if (((ca >= 'A') && (ca <= 'Z')))
        {
            (ca = (char)(((ca - 'A') + 'a')));
        }
        char cb = b.ptr[i];
        if (((cb >= 'A') && (cb <= 'Z')))
        {
            (cb = (char)(((cb - 'A') + 'a')));
        }
        if ((ca != cb))
        {
            return false;
        }
    }
    return true;
}

