void ast_freeExpr(ast_Expr* e)
{
    if ((e == NULL))
    {
        return;
    }
    switch (e->kind)
    {
        case ast_EX_BINARY:
            ast_freeExpr(e->a);
            ast_freeExpr(e->b);
            break;
        case ast_EX_UNARY:
        case ast_EX_DEREF:
        case ast_EX_ADDR:
            ast_freeExpr(e->a);
            break;
        case ast_EX_TERNARY:
            ast_freeExpr(e->a);
            ast_freeExpr(e->b);
            ast_freeExpr(e->c);
            break;
        case ast_EX_CALL:
        case ast_EX_INIT:
            ast_freeExpr(e->a);
            if (e->args)
            {
                for (uint32_t k = 0; (k < e->nargs); (k++))
                {
                    ast_freeExpr(e->args[k]);
                }
                mman_dealloc_ast_Expr_ptr(e->args);
            }
            if (e->names)
            {
                mman_dealloc_str_strView(e->names);
            }
            break;
        case ast_EX_DOT:
        case ast_EX_ARROW:
            ast_freeExpr(e->a);
            break;
        case ast_EX_INDEX:
            ast_freeExpr(e->a);
            ast_freeExpr(e->b);
            break;
        case ast_EX_PAREN:
            ast_freeExpr(e->a);
            break;
        case ast_EX_GENERIC:
            ast_freeExpr(e->a);
            if (e->args)
            {
                for (uint32_t k = 0; (k < e->nargs); (k++))
                {
                    ast_freeExpr(e->args[k]);
                }
                mman_dealloc_ast_Expr_ptr(e->args);
            }
            ast_freeType(e->type);
            break;
        case ast_EX_CAST:
            ast_freeExpr(e->a);
            ast_freeType(e->type);
            break;
        case ast_EX_SIZEOF:
        case ast_EX_TYPELIT:
            ast_freeType(e->type);
            break;
        default:
            break;
    }
    mman_dealloc_ast_Expr(e);
}

void ast_freeType(ast_TypeExpr* t)
{
    if ((t == NULL))
    {
        return;
    }
    if (t->args)
    {
        for (uint32_t k = 0; (k < t->nargs); (k++))
        {
            ast_freeType(t->args[k]);
        }
        mman_dealloc_ast_TypeExpr_ptr(t->args);
    }
    if (t->cargs)
    {
        for (uint32_t k = 0; (k < t->ncargs); (k++))
        {
            ast_freeExpr(t->cargs[k]);
        }
        mman_dealloc_ast_Expr_ptr(t->cargs);
    }
    ast_freeType(t->elem);
    ast_freeType(t->ret);
    ast_freeExpr(t->count);
    mman_dealloc_ast_TypeExpr(t);
}

void ast_freeStmt(ast_Stmt* s)
{
    if ((s == NULL))
    {
        return;
    }
    ast_freeStmt(s->init);
    ast_freeStmt(s->body);
    ast_freeStmt(s->body2);
    ast_freeExpr(s->a);
    ast_freeExpr(s->b);
    ast_freeExpr(s->c);
    if (s->stmts)
    {
        for (uint32_t k = 0; (k < s->nstmts); (k++))
        {
            ast_freeStmt(s->stmts[k]);
        }
        mman_dealloc_ast_Stmt_ptr(s->stmts);
    }
    if (s->cases)
    {
        for (uint32_t k = 0; (k < s->ncases); (k++))
        {
            ast_StmtCase* sc = s->cases[k];
            if (sc)
            {
                if (sc->body)
                {
                    for (uint32_t j = 0; (j < sc->nbody); (j++))
                    {
                        ast_freeStmt(sc->body[j]);
                    }
                    mman_dealloc_ast_Stmt_ptr(sc->body);
                }
                ast_freeExpr(sc->value);
                mman_dealloc_ast_StmtCase(sc);
            }
        }
        mman_dealloc_ast_StmtCase_ptr(s->cases);
    }
    if (s->defaultCase)
    {
        ast_StmtCase* sc = s->defaultCase;
        if (sc->body)
        {
            for (uint32_t j = 0; (j < sc->nbody); (j++))
            {
                ast_freeStmt(sc->body[j]);
            }
            mman_dealloc_ast_Stmt_ptr(sc->body);
        }
        ast_freeExpr(sc->value);
        mman_dealloc_ast_StmtCase(sc);
    }
    ast_freeType(s->type);
    mman_dealloc_ast_Stmt(s);
}

void ast_freeDecl(ast_Decl* d)
{
    if ((d == NULL))
    {
        return;
    }
    ast_freeType(d->type);
    ast_freeExpr(d->value);
    if (d->generics)
    {
        mman_dealloc_str_strView(d->generics);
    }
    if (d->params)
    {
        mman_dealloc_ast_Param(d->params);
    }
    if (d->fields)
    {
        for (uint32_t k = 0; (k < d->nfields); (k++))
        {
            ast_freeType(d->fields[k].type);
        }
        mman_dealloc_ast_StructField(d->fields);
    }
    if (d->variants)
    {
        for (uint32_t k = 0; (k < d->nvariants); (k++))
        {
            ast_freeExpr(d->variants[k].value);
        }
        mman_dealloc_ast_EnumVariant(d->variants);
    }
    if (d->decls)
    {
        for (uint32_t k = 0; (k < d->ndecls); (k++))
        {
            ast_freeDecl(d->decls[k]);
        }
        mman_dealloc_ast_Decl_ptr(d->decls);
    }
    if (d->cases)
    {
        for (uint32_t k = 0; (k < d->ncases); (k++))
        {
            ast_freeDecl(d->cases[k]);
        }
        mman_dealloc_ast_Decl_ptr(d->cases);
    }
    if (d->caseNames)
    {
        mman_dealloc_str_strView(d->caseNames);
    }
    if (d->caseLens)
    {
        mman_dealloc_u32(d->caseLens);
    }
    if (d->defaultBody)
    {
        for (uint32_t k = 0; (k < d->ndeclDefault); (k++))
        {
            ast_freeDecl(d->defaultBody[k]);
        }
        mman_dealloc_ast_Decl_ptr(d->defaultBody);
    }
    ast_freeStmt(d->body);
    mman_dealloc_ast_Decl(d);
}

void ast_freeProgram(ast_Program* p)
{
    if ((p == NULL))
    {
        return;
    }
    if (p->decls)
    {
        for (uint32_t k = 0; (k < p->ndecls); (k++))
        {
            ast_freeDecl(p->decls[k]);
        }
        mman_dealloc_ast_Decl_ptr(p->decls);
    }
    mman_dealloc_ast_Program(p);
}

str_strView error_extractLine(str_strView src, uint32_t line)
{
    uint64_t idx = 0;
    uint32_t cur = 1;
    while (((cur < line) && (idx < src.len)))
    {
        if ((src.ptr[idx] == '\n'))
        {
            (cur++);
        }
        (idx++);
    }
    if ((cur < line))
    {
        return str_strView_empty();
    }
    uint64_t start = idx;
    while (((idx < src.len) && (src.ptr[idx] != '\n')))
    {
        (idx++);
    }
    return str_strView_fromParts((src.ptr + start), (idx - start));
}

void error_pushUint(str_String* s, uint32_t v)
{
    uint8_t tmp[20];
    int32_t n = snprintf(tmp, 20, "%u", v);
    if ((n < 0))
    {
        (n = 0);
    }
    if (((uint64_t)n > 20))
    {
        (n = 20);
    }
    str_String_pushView(s, str_strView_fromParts((const char*)tmp, (uint64_t)n));
}

uint32_t error_digits(uint32_t v)
{
    uint32_t d = 1;
    while ((v >= 10))
    {
        (v /= 10);
        (d++);
    }
    return d;
}

void error_pushPadUint(str_String* s, uint32_t v, uint32_t w)
{
    uint32_t d = error_digits(v);
    if ((w > d))
    {
        for (uint32_t i = 0; (i < (w - d)); (i++))
        {
            str_String_pushChar(s, ' ');
        }
    }
    error_pushUint(s, v);
}

void error_diag(str_strView code, str_strView filename, str_strView src, uint32_t line, uint32_t col, uint8_t level, str_strView msg, str_strView help)
{
    str_String s = str_String_new();
    uint8_t ESC = 27;
    str_strView C_RESET = str_strView_fromCstr("[0m");
    str_strView C_LEVEL = str_strView_fromCstr("[1;31m");
    str_strView C_CODE = str_strView_fromCstr("[35m");
    str_strView C_BOX = str_strView_fromCstr("[90m");
    str_strView C_CARET = str_strView_fromCstr("[1;31m");
    str_strView C_HELP = str_strView_fromCstr("[36m");
    if ((level == error_LVL_WARN))
    {
        (C_LEVEL = str_strView_fromCstr("[33m"));
    }
    else
    if (((level == error_LVL_INFO) || (level == error_LVL_NOTE)))
    {
        (C_LEVEL = str_strView_fromCstr("[36m"));
    }
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_LEVEL);
    if ((level == error_LVL_ERROR))
    {
        str_String_pushView(&s, str_strView_fromCstr("error"));
    }
    else
    if ((level == error_LVL_WARN))
    {
        str_String_pushView(&s, str_strView_fromCstr("warning"));
    }
    else
    if ((level == error_LVL_INFO))
    {
        str_String_pushView(&s, str_strView_fromCstr("info"));
    }
    else
    {
        str_String_pushView(&s, str_strView_fromCstr("note"));
    }
    if ((code.len > 0))
    {
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_CODE);
        str_String_pushChar(&s, '[');
        str_String_pushView(&s, code);
        str_String_pushChar(&s, ']');
    }
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_RESET);
    str_String_pushView(&s, str_strView_fromCstr(": "));
    str_String_pushView(&s, msg);
    str_String_pushChar(&s, '\n');
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_BOX);
    str_String_pushView(&s, str_strView_fromCstr("  ┌─► "));
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_RESET);
    str_String_pushView(&s, filename);
    str_String_pushChar(&s, ':');
    error_pushUint((&s), line);
    str_String_pushChar(&s, ':');
    error_pushUint((&s), col);
    str_String_pushChar(&s, '\n');
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_BOX);
    str_String_pushView(&s, str_strView_fromCstr("  │\n"));
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_RESET);
    uint32_t numW = error_digits(line);
    if ((numW < 2))
    {
        (numW = 2);
    }
    for (int32_t off = (-1); (off <= 0); (off++))
    {
        int32_t ln = ((int32_t)line + off);
        if ((ln < 1))
        {
            continue;
        }
        str_strView lt = error_extractLine(src, (uint32_t)ln);
        if (((lt.len == 0) && (off != 0)))
        {
            continue;
        }
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_BOX);
        str_String_pushView(&s, str_strView_fromCstr("  │ "));
        error_pushPadUint((&s), (uint32_t)ln, numW);
        str_String_pushView(&s, str_strView_fromCstr(" │ "));
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_RESET);
        str_String_pushView(&s, lt);
        str_String_pushChar(&s, '\n');
    }
    uint32_t prefixLen = ((4 + numW) + 3);
    int32_t caretSpaces = (((int32_t)prefixLen + (int32_t)col) - 4);
    if ((caretSpaces < 0))
    {
        (caretSpaces = 0);
    }
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_BOX);
    str_String_pushView(&s, str_strView_fromCstr("  |"));
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_RESET);
    for (int32_t i = 0; (i < caretSpaces); (i++))
    {
        str_String_pushChar(&s, ' ');
    }
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_CARET);
    str_String_pushView(&s, str_strView_fromCstr("▲"));
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, C_RESET);
    str_String_pushChar(&s, '\n');
    if ((help.len > 0))
    {
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_BOX);
        str_String_pushView(&s, str_strView_fromCstr("  │"));
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_RESET);
        for (int32_t i = 0; (i < caretSpaces); (i++))
        {
            str_String_pushChar(&s, ' ');
        }
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_BOX);
        str_String_pushView(&s, str_strView_fromCstr("╰─ "));
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_HELP);
        str_String_pushView(&s, help);
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_RESET);
        str_String_pushChar(&s, '\n');
    }
    if ((code.len > 0))
    {
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_BOX);
        str_String_pushView(&s, str_strView_fromCstr("  │"));
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_RESET);
        for (int32_t i = 0; (i < caretSpaces); (i++))
        {
            str_String_pushChar(&s, ' ');
        }
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_BOX);
        str_String_pushView(&s, str_strView_fromCstr("╰─ "));
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, str_strView_fromCstr("[90m"));
        str_String_pushView(&s, str_strView_fromCstr("try `coralc --explain "));
        str_String_pushView(&s, code);
        str_String_pushView(&s, str_strView_fromCstr("` for more information"));
        str_String_pushChar(&s, (char)ESC);
        str_String_pushView(&s, C_RESET);
        str_String_pushChar(&s, '\n');
    }
    write(2, str_String_asU8(&s), s.len);
    str_String_free(&s);
}

void error_reportLevel(str_strView filename, str_strView src, uint32_t line, uint32_t col, uint8_t level, str_strView msg, str_strView ctx)
{
    error_diag(str_strView_empty(), filename, src, line, col, level, msg, ctx);
}

void error_reportCode(str_strView code, str_strView filename, str_strView src, uint32_t line, uint32_t col, uint8_t level, str_strView msg, str_strView help)
{
    error_diag(code, filename, src, line, col, level, msg, help);
}

void error_report(str_strView filename, str_strView src, uint32_t line, uint32_t col, str_strView msg, str_strView ctx)
{
    error_reportLevel(filename, src, line, col, error_LVL_ERROR, msg, ctx);
}

bool error_codeEq(str_strView a, const char* b)
{
    uint64_t n = 0;
    while (b[n])
    {
        (n++);
    }
    if ((a.len != n))
    {
        return false;
    }
    for (uint64_t i = 0; (i < n); (i++))
    {
        if ((a.ptr[i] != (uint8_t)b[i]))
        {
            return false;
        }
    }
    return true;
}

void error_explain(str_strView code)
{
    bool found = false;
    uint8_t ESC = 27;
    str_String s = str_String_new();
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, str_strView_fromCstr("[1m"));
    str_String_pushView(&s, code);
    str_String_pushChar(&s, (char)ESC);
    str_String_pushView(&s, str_strView_fromCstr("[0m"));
    str_String_pushView(&s, str_strView_fromCstr(" — "));
    if (error_codeEq(code, "LEX-0001"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The lexer found a character it doesn't recognise as valid Coral syntax.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("This usually means:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - A stray symbol (e.g. `@`, `$`, `#`) outside a string or comment\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - An attempt to use `@[attr]` or `@name` syntax (not valid in Coral)\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Attributes use double brackets: [[reorder]], [[packed]], or @[[no_warn_unsafe]] at file level.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "LEX-0003"))
    {
        str_String_pushView(&s, str_strView_fromCstr("A string literal was opened but never closed before the end of the line.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Every `\"` needs a matching closing `\"` on the same line.\n"));
        str_String_pushView(&s, str_strView_fromCstr("For multi-line strings, use triple quotes: \"\"\" ... \"\"\"\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "LEX-0004"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The lexer could not parse this as a number.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Valid forms: 42, 0xFF, 0b1010, 0o777, 3.14, 42u, 42ul\n"));
        str_String_pushView(&s, str_strView_fromCstr("Common mistakes: two decimal points (1.2.3), invalid digit for radix (0xGG), trailing comma.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "LEX-0005"))
    {
        str_String_pushView(&s, str_strView_fromCstr("A char literal is malformed.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Char literals are single characters in single quotes: 'a', '\\n', '\\t'\n"));
        str_String_pushView(&s, str_strView_fromCstr("Empty ('') or multi-character ('ab') literals are not allowed. Use \"a\" for strings.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "LEX-0006"))
    {
        str_String_pushView(&s, str_strView_fromCstr("A /* block comment was opened but never closed with */ before end of file.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Add the closing */ or delete the opening /*.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "LEX-0007"))
    {
        str_String_pushView(&s, str_strView_fromCstr("Invalid attribute syntax. Coral uses double brackets, not @-prefixed names.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Correct forms:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  [[reorder]]          on a struct declaration\n"));
        str_String_pushView(&s, str_strView_fromCstr("  [[packed]]           on a struct declaration\n"));
        str_String_pushView(&s, str_strView_fromCstr("  [[reorder, packed]]  combined on one line\n"));
        str_String_pushView(&s, str_strView_fromCstr("  @[[no_warn_unsafe]]  at file level (first line)\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("@[name] and bare @name are NOT valid Coral syntax.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "SYN-1002"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The parser expected a closing '>' to match an opening '<'.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Generic argument lists look like <T> or <T, U> and must be closed with >.\n"));
        str_String_pushView(&s, str_strView_fromCstr("Check that every < has a matching > nearby.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "SYN-1003"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The parser hit a token it didn't expect in this position.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("At file level, valid declarations start with:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  mod, pub, struct, enum, trait, const, var, extern, import, flag\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Inside functions, statements start with:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  var, return, if, for, while, loop, switch, defer, break, continue\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "SYN-1998"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The parser couldn't parse this as a valid declaration.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Common causes:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Missing semicolon after a field or variable\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Missing () around parameters\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Missing {} around a body\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "SYN-1999"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The parser failed to produce a valid program from this input.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("This usually means an unclosed brace, bracket, or parenthesis somewhere earlier in the file.\n"));
        str_String_pushView(&s, str_strView_fromCstr("Try checking that every { has a matching }, and every ( has a matching ).\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-TYPE"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The compiler doesn't recognise this type name.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Built-in primitives:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  i8 i16 i32 i64  u8 u16 u32 u64  f32 f64\n"));
        str_String_pushView(&s, str_strView_fromCstr("  bool char void isize usize\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("User-defined types must be declared before use:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  struct Name { ... }   enum Name { ... }\n"));
        str_String_pushView(&s, str_strView_fromCstr("  typedef Name = ExistingType;\n"));
        str_String_pushView(&s, str_strView_fromCstr("  distinct Name = ExistingType;\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("If the type lives in another module, import it first:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  mod m = import(lib, \"module_name\");\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-RETURN"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The return statement doesn't match the function's declared return type.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Three possible causes:\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("1. Void function returning a value:\n"));
        str_String_pushView(&s, str_strView_fromCstr("   void foo() { return 42; }  ← wrong\n"));
        str_String_pushView(&s, str_strView_fromCstr("   Fix: remove the value, or change return type\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("2. Non-void function missing a return:\n"));
        str_String_pushView(&s, str_strView_fromCstr("   i32 foo() { }  ← no return statement\n"));
        str_String_pushView(&s, str_strView_fromCstr("   Fix: add `return <value>;` on every path\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("3. Returned value's type ≠ declared return type:\n"));
        str_String_pushView(&s, str_strView_fromCstr("   f64 foo() { return 42; }  ← 42 is int, not float\n"));
        str_String_pushView(&s, str_strView_fromCstr("   Fix: cast explicitly: return 42.0;\n"));
        str_String_pushView(&s, str_strView_fromCstr("   Note: distinct types need explicit casts both ways.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-ASSIGN"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The right-hand side's type doesn't match the left-hand side.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Coral has NO implicit conversions between different types.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("What IS allowed:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Exact same type\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Lossless integer widening (u8 → u32, i8 → i64)\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Integer literal fitting target type\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("What is NOT allowed:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - u32 → i32 (sign change)\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - distinct types without explicit cast\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Fix: add an explicit cast `(T)expr` or change the value's type.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-ARGS"))
    {
        str_String_pushView(&s, str_strView_fromCstr("A function call argument doesn't match its parameter.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Check:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  1. Number of arguments matches number of parameters\n"));
        str_String_pushView(&s, str_strView_fromCstr("  2. Each argument's type matches its parameter's type exactly\n"));
        str_String_pushView(&s, str_strView_fromCstr("  3. distinct-typed arguments need explicit casts\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Example:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  fn take(u32 x) { }\n"));
        str_String_pushView(&s, str_strView_fromCstr("  take(-1);       ← wrong: i32 literal doesn't fit u32\n"));
        str_String_pushView(&s, str_strView_fromCstr("  take(1);         ← OK: fits u32\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-NONULL"))
    {
        str_String_pushView(&s, str_strView_fromCstr("null was passed to a parameter marked [[nonull]].\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("The callee promises this pointer is never null.\n"));
        str_String_pushView(&s, str_strView_fromCstr("Either add a null check before calling, or pass a real pointer.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-BORROW"))
    {
        str_String_pushView(&s, str_strView_fromCstr("Two pointers may alias the same memory region while one is written to.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("This is a conservative check. Three patterns trigger it:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Two pointer args to one call point to the same data\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - A load stays live across a call that writes through a pointer\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - A store happens while an earlier load is still needed\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Fix: copy the value, use separate allocations, or reorder operations.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-ACCESS"))
    {
        str_String_pushView(&s, str_strView_fromCstr("You tried to access a module member that isn't exported.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Only declarations marked `pub` are visible outside their module:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  pub struct Foo { }     ← visible\n"));
        str_String_pushView(&s, str_strView_fromCstr("  struct Bar { }          ← private\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Also check that the module alias is correct and imported.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-ARITH"))
    {
        str_String_pushView(&s, str_strView_fromCstr("Arithmetic applied to incompatible or non-numeric operands.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("+ - * / %% require numeric types (integers or floats).\n"));
        str_String_pushView(&s, str_strView_fromCstr("& | ^ << >> require integers.\n"));
        str_String_pushView(&s, str_strView_fromCstr("distinct types don't implicitly convert — cast first.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Example:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  distinct Meters = u64;\n"));
        str_String_pushView(&s, str_strView_fromCstr("  distinct Feet = u64;\n"));
        str_String_pushView(&s, str_strView_fromCstr("  m + f  ← error: can't mix Meters and Feet\n"));
        str_String_pushView(&s, str_strView_fromCstr("  m + (Meters)f  ← OK after explicit cast\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-COND"))
    {
        str_String_pushView(&s, str_strView_fromCstr("An if/while/for condition must be bool.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Coral does NOT allow integers as implicit conditions:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  if (x)      ← error when x is int\n"));
        str_String_pushView(&s, str_strView_fromCstr("  if (x != 0) ← correct\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Valid condition operators: == != < > <= >= && || !\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-DUP"))
    {
        str_String_pushView(&s, str_strView_fromCstr("Two parameters in the same function have the same name.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Rename one of them.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-ENUM"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The named variant doesn't exist in this enum.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Check spelling against the enum definition:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  enum Color { Red, Green, Blue }\n"));
        str_String_pushView(&s, str_strView_fromCstr("  Color.Red ✓   Color.redd ✗\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-EXPR"))
    {
        str_String_pushView(&s, str_strView_fromCstr("An expression's result type doesn't fit where it's used.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Common causes:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Mixing int and float without cast\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Using void call result in an expression\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Type mismatch between operands of a binary operator\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Add an explicit cast or fix the operand types.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-INDEX"))
    {
        str_String_pushView(&s, str_strView_fromCstr("Array index out of bounds, or indexing something that isn't indexable.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("For fixed arrays arr[N], index must be 0..N-1.\n"));
        str_String_pushView(&s, str_strView_fromCstr("Only arrays, slices, and pointers can be indexed.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-MEMBER"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The struct/enum/module doesn't have a member by this name.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Check:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  1. Spelling of the field/method name\n"));
        str_String_pushView(&s, str_strView_fromCstr("  2. The field exists in the struct definition\n"));
        str_String_pushView(&s, str_strView_fromCstr("  3. For methods: the method is defined on this struct\n"));
        str_String_pushView(&s, str_strView_fromCstr("  4. If accessing across modules: the member is pub\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-REDECL"))
    {
        str_String_pushView(&s, str_strView_fromCstr("This name is already used in the current scope.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Each scope can only have one declaration per name:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  i32 x = 1;\n"));
        str_String_pushView(&s, str_strView_fromCstr("  i32 x = 2;  ← error: x already declared\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Shadowing in nested scopes is allowed:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  i32 x = 1;\n"));
        str_String_pushView(&s, str_strView_fromCstr("  { i32 x = 2; }  ← OK: inner scope\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-RESOLVE"))
    {
        str_String_pushView(&s, str_strView_fromCstr("The compiler can't find this name in any accessible scope.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Possible fixes:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  1. Check spelling — Coral is case-sensitive\n"));
        str_String_pushView(&s, str_strView_fromCstr("  2. Import the module that defines it:\n"));
        str_String_pushView(&s, str_strView_fromCstr("     mod m = import(lib, \"module\");\n"));
        str_String_pushView(&s, str_strView_fromCstr("  3. Declare it before use\n"));
        str_String_pushView(&s, str_strView_fromCstr("  4. If it's a struct method, verify the struct is in scope\n"));
        str_String_pushView(&s, str_strView_fromCstr("  5. If it's inside a flag block, make sure the flag resolves\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-STRUCT"))
    {
        str_String_pushView(&s, str_strView_fromCstr("A struct initializer references a field that doesn't exist, or a field's type doesn't match.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Struct literal syntax:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  Point p = Point { .x = 1, .y = 2 };\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Every field name must match the struct definition exactly.\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-SWITCH"))
    {
        str_String_pushView(&s, str_strView_fromCstr("A switch case value doesn't match the switch subject's type.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("All case values must be the same type as the thing being switched on:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  switch(x) { case 1: ... }  ← 1 must be same type as x\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-UNUSED"))
    {
        str_String_pushView(&s, str_strView_fromCstr("This variable is declared but never read anywhere.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("This is a WARNING, not an error — your program still compiles.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("To silence it:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Remove the variable if you don't need it\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Prefix with _ (_count) to indicate intentional discard\n"));
        str_String_pushView(&s, str_strView_fromCstr("  - Or just ignore the warning\n"));
        (found = true);
    }
    else
    if (error_codeEq(code, "TC-CONSTEXPR"))
    {
        str_String_pushView(&s, str_strView_fromCstr("A constexpr initializer must evaluate at compile time.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Only literals and constant expressions qualify:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  constexpr u32 N = 42;       ← OK\n"));
        str_String_pushView(&s, str_strView_fromCstr("  constexpr u32 M = N * 2;    ← OK\n"));
        str_String_pushView(&s, str_strView_fromCstr("  constexpr u32 X = some_fn(); ← error: runtime call\n"));
        (found = true);
    }
    if ((!found))
    {
        str_String_pushView(&s, str_strView_fromCstr("No explanation available for this code.\n\n"));
        str_String_pushView(&s, str_strView_fromCstr("Available codes:\n"));
        str_String_pushView(&s, str_strView_fromCstr("  LEX-0001  LEX-0003  LEX-0004  LEX-0005  LEX-0006  LEX-0007\n"));
        str_String_pushView(&s, str_strView_fromCstr("  SYN-1002  SYN-1003  SYN-1998  SYN-1999\n"));
        str_String_pushView(&s, str_strView_fromCstr("  TC-TYPE TC-RETURN TC-ASSIGN TC-ARGS TC-NONULL TC-BORROW\n"));
        str_String_pushView(&s, str_strView_fromCstr("  TC-ACCESS TC-ARITH TC-COND TC-DUP TC-ENUM TC-EXPR TC-INDEX\n"));
        str_String_pushView(&s, str_strView_fromCstr("  TC-MEMBER TC-REDECL TC-RESOLVE TC-STRUCT TC-SWITCH\n"));
        str_String_pushView(&s, str_strView_fromCstr("  TC-UNUSED TC-CONSTEXPR\n"));
    }
    str_String_pushChar(&s, '\n');
    write(1, str_String_asU8(&s), s.len);
    str_String_free(&s);
}

bool parse_vEq(str_strView a, const char* b)
{
    uint32_t i = 0;
    while ((b[i] != 0))
    {
        if (((i >= a.len) || (a.ptr[i] != b[i])))
        {
            return false;
        }
        (i++);
    }
    return (i == a.len);
}

uint32_t parse_assignOpPrec(uint32_t tid)
{
    if ((((((((((((tid == tok_T_ASSIGN) || (tid == tok_T_PLUS_EQ)) || (tid == tok_T_MINUS_EQ)) || (tid == tok_T_STAR_EQ)) || (tid == tok_T_SLASH_EQ)) || (tid == tok_T_PERCENT_EQ)) || (tid == tok_T_AMP_EQ)) || (tid == tok_T_PIPE_EQ)) || (tid == tok_T_CARET_EQ)) || (tid == tok_T_SHL_EQ)) || (tid == tok_T_SHR_EQ)))
    {
        return parse_P_ASSIGN;
    }
    return parse_NO_PREC;
}

str_strView parse_assignOpText(uint32_t tid)
{
    switch (tid)
    {
        case tok_T_ASSIGN:
            return str_strView_fromCstr("=");
        case tok_T_PLUS_EQ:
            return str_strView_fromCstr("+=");
        case tok_T_MINUS_EQ:
            return str_strView_fromCstr("-=");
        case tok_T_STAR_EQ:
            return str_strView_fromCstr("*=");
        case tok_T_SLASH_EQ:
            return str_strView_fromCstr("/=");
        case tok_T_PERCENT_EQ:
            return str_strView_fromCstr("%=");
        case tok_T_AMP_EQ:
            return str_strView_fromCstr("&=");
        case tok_T_PIPE_EQ:
            return str_strView_fromCstr("|=");
        case tok_T_CARET_EQ:
            return str_strView_fromCstr("^=");
        case tok_T_SHL_EQ:
            return str_strView_fromCstr("<<=");
        case tok_T_SHR_EQ:
            return str_strView_fromCstr(">>=");
    }
    return str_strView_empty();
}

uint32_t parse_binOpPrec(uint32_t tid)
{
    switch (tid)
    {
        case tok_T_OR:
            return parse_P_OR;
        case tok_T_AND:
            return parse_P_AND;
        case tok_T_PIPE:
            return parse_P_BITOR;
        case tok_T_CARET:
            return parse_P_BITXOR;
        case tok_T_AMP:
            return parse_P_BITAND;
        case tok_T_EQ:
            return parse_P_EQ;
        case tok_T_NE:
            return parse_P_EQ;
        case tok_T_LT:
            return parse_P_CMP;
        case tok_T_LE:
            return parse_P_CMP;
        case tok_T_GT:
            return parse_P_CMP;
        case tok_T_GE:
            return parse_P_CMP;
        case tok_T_SHL:
            return parse_P_SHIFT;
        case tok_T_SHR:
            return parse_P_SHIFT;
        case tok_T_PLUS:
            return parse_P_ADD;
        case tok_T_MINUS:
            return parse_P_ADD;
        case tok_T_STAR:
            return parse_P_MUL;
        case tok_T_SLASH:
            return parse_P_MUL;
        case tok_T_PERCENT:
            return parse_P_MUL;
    }
    return parse_NO_PREC;
}

str_strView parse_binOpText(uint32_t tid)
{
    switch (tid)
    {
        case tok_T_OR:
            return str_strView_fromCstr("||");
        case tok_T_AND:
            return str_strView_fromCstr("&&");
        case tok_T_PIPE:
            return str_strView_fromCstr("|");
        case tok_T_CARET:
            return str_strView_fromCstr("^");
        case tok_T_AMP:
            return str_strView_fromCstr("&");
        case tok_T_EQ:
            return str_strView_fromCstr("==");
        case tok_T_NE:
            return str_strView_fromCstr("!=");
        case tok_T_LT:
            return str_strView_fromCstr("<");
        case tok_T_LE:
            return str_strView_fromCstr("<=");
        case tok_T_GT:
            return str_strView_fromCstr(">");
        case tok_T_GE:
            return str_strView_fromCstr(">=");
        case tok_T_SHL:
            return str_strView_fromCstr("<<");
        case tok_T_SHR:
            return str_strView_fromCstr(">>");
        case tok_T_PLUS:
            return str_strView_fromCstr("+");
        case tok_T_MINUS:
            return str_strView_fromCstr("-");
        case tok_T_STAR:
            return str_strView_fromCstr("*");
        case tok_T_SLASH:
            return str_strView_fromCstr("/");
        case tok_T_PERCENT:
            return str_strView_fromCstr("%");
    }
    return str_strView_empty();
}

bool parse_prefixOpText(uint32_t tid, str_strView* out)
{
    switch (tid)
    {
        case tok_T_PLUS:
            ((*out) = str_strView_fromCstr("+"));
            return true;
        case tok_T_MINUS:
            ((*out) = str_strView_fromCstr("-"));
            return true;
        case tok_T_BANG:
            ((*out) = str_strView_fromCstr("!"));
            return true;
        case tok_T_TILDE:
            ((*out) = str_strView_fromCstr("~"));
            return true;
        case tok_T_STAR:
            ((*out) = str_strView_fromCstr("*"));
            return true;
        case tok_T_AMP:
            ((*out) = str_strView_fromCstr("&"));
            return true;
        case tok_T_INC:
            ((*out) = str_strView_fromCstr("++"));
            return true;
        case tok_T_DEC:
            ((*out) = str_strView_fromCstr("--"));
            return true;
    }
    return false;
}

parse_Parser parse_Parser_new(tok_LexTok* toks, uint32_t n, const uint8_t* src, uint32_t srclen, str_strView filename)
{
    parse_Parser p;
    (p.toks = toks);
    (p.n = n);
    (p.pos = 0);
    (p.filename = filename);
    (p.source = str_strView_fromParts((const char*)src, srclen));
    (p.nctx = 0);
    (p.errored = false);
    (p.errMsg = str_String_new());
    (p.errCtx = str_String_new());
    (p.errCode = str_String_new());
    (p.errHelp = str_String_new());
    (p.nattrs = 0);
    (p.gtgtConsumed = false);
    (p.decls = NULL);
    (p.ndecls = 0);
    (p.declCap = 0);
    (p.lastStallPos = 0);
    (p.stallCount = 0);
    (p.fattrs = NULL);
    (p.nfattrs = 0);
    (p.fattrsCap = 0);
    (p.recordAttrs = false);
    return p;
}

tok_LexTok* parse_Parser_peekTok(parse_Parser* self, int32_t off)
{
    int32_t i = ((int32_t)self->pos + off);
    if ((i < 0))
    {
        (i = 0);
    }
    if ((i >= (int32_t)self->n))
    {
        (i = ((int32_t)self->n - 1));
    }
    return (&self->toks[i]);
}

bool parse_Parser_check(parse_Parser* self, uint32_t t)
{
    return (parse_Parser_peekTok(self, 0)->id == t);
}

bool parse_Parser_checkStr(parse_Parser* self, const char* s)
{
    return ((parse_Parser_peekTok(self, 0)->id == tok_TOK_IDENT) && parse_vEq(parse_Parser_curText(self), s));
}

tok_LexTok* parse_Parser_advance(parse_Parser* self)
{
    tok_LexTok* t = (&self->toks[self->pos]);
    if (((self->pos + 1) < self->n))
    {
        (self->pos++);
    }
    return t;
}

str_strView parse_Parser_text(parse_Parser* self, tok_LexTok* t)
{
    return str_strView_fromParts((self->source.ptr + t->start), t->len);
}

str_strView parse_Parser_curText(parse_Parser* self)
{
    return parse_Parser_text(self, parse_Parser_peekTok(self, 0));
}

bool parse_Parser_isTypeTok(parse_Parser* self, tok_LexTok* t)
{
    uint32_t id = t->id;
    return ((id >= tok_T_I8) && (id <= tok_T_USIZE));
}

bool parse_Parser_isNameTok(parse_Parser* self, tok_LexTok* t)
{
    return ((t->id == tok_TOK_IDENT) || parse_Parser_isTypeTok(self, t));
}

str_strView parse_Parser_span(parse_Parser* self, uint32_t s, uint32_t e)
{
    return str_strView_fromParts((self->source.ptr + s), (e - s));
}

void parse_Parser_ctxPush(parse_Parser* self, uint32_t kind, str_strView name, str_strView name2)
{
    if ((self->nctx < 8))
    {
        (self->ctx[self->nctx].kind = kind);
        (self->ctx[self->nctx].name = name);
        (self->ctx[self->nctx].name2 = name2);
        (self->nctx++);
    }
}

void parse_Parser_ctxPop(parse_Parser* self)
{
    if ((self->nctx > 0))
    {
        (self->nctx--);
    }
}

void parse_Parser_appendCtxLabel(parse_Parser* self, str_String* out, parse_CtxEntry* e)
{
    if ((e->kind == parse_CTX_STRUCT))
    {
        str_String_pushView(out, str_strView_fromCstr("struct "));
    }
    else
    if ((e->kind == parse_CTX_ENUM))
    {
        str_String_pushView(out, str_strView_fromCstr("enum "));
    }
    else
    if ((e->kind == parse_CTX_TRAIT))
    {
        str_String_pushView(out, str_strView_fromCstr("trait "));
    }
    else
    if ((e->kind == parse_CTX_FLAG))
    {
        str_String_pushView(out, str_strView_fromCstr("flag "));
    }
    else
    if ((e->kind == parse_CTX_FUNC))
    {
        str_String_pushView(out, str_strView_fromCstr("function "));
    }
    else
    if ((e->kind == parse_CTX_METHODS))
    {
        str_String_pushView(out, str_strView_fromCstr("methods of "));
    }
    else
    if ((e->kind == parse_CTX_TRAITIMPL))
    {
        str_String_pushView(out, str_strView_fromCstr("trait impl "));
    }
    else
    {
        str_String_pushView(out, str_strView_fromCstr("declaration of "));
    }
    str_String_pushView(out, e->name);
    if ((e->name2.len > 0))
    {
        str_String_pushView(out, str_strView_fromCstr(" :: "));
        str_String_pushView(out, e->name2);
    }
}

void parse_Parser_setErrAt(parse_Parser* self, tok_LexTok* t, str_String* msg, str_String* code, str_String* help)
{
    if (self->errored)
    {
        return;
    }
    (self->errored = true);
    (self->errLine = t->row);
    (self->errCol = t->col);
    str_String_free(&self->errMsg);
    (self->errMsg = str_String_new());
    for (uint64_t i = 0; (i < msg->len); (i++))
    {
        str_String_pushChar(&self->errMsg, msg->ptr[i]);
    }
    str_String_free(&self->errCode);
    (self->errCode = str_String_new());
    if ((code != NULL))
    {
        for (uint64_t i = 0; (i < code->len); (i++))
        {
            str_String_pushChar(&self->errCode, code->ptr[i]);
        }
    }
    str_String_free(&self->errHelp);
    (self->errHelp = str_String_new());
    if ((help != NULL))
    {
        for (uint64_t i = 0; (i < help->len); (i++))
        {
            str_String_pushChar(&self->errHelp, help->ptr[i]);
        }
    }
    str_String_free(&self->errCtx);
    (self->errCtx = str_String_new());
    if ((self->nctx > 0))
    {
        uint32_t base = 0;
        if ((self->nctx > 3))
        {
            (base = (self->nctx - 3));
        }
        for (uint32_t i = base; (i < self->nctx); (i++))
        {
            if ((i > base))
            {
                str_String_pushView(&self->errCtx, str_strView_fromCstr(" -> "));
            }
            parse_Parser_appendCtxLabel(self, (&self->errCtx), (&self->ctx[i]));
        }
    }
}

void parse_Parser_setErr(parse_Parser* self, tok_LexTok* t, const char* code, const char* m, const char* help)
{
    if (self->errored)
    {
        return;
    }
    str_String s = str_String_new();
    str_String_pushView(&s, str_strView_fromCstr(m));
    str_String c = str_String_new();
    str_String_pushView(&c, str_strView_fromCstr(code));
    str_String h = str_String_new();
    if ((help != NULL))
    {
        str_String_pushView(&h, str_strView_fromCstr(help));
    }
    parse_Parser_setErrAt(self, t, (&s), (&c), (&h));
    str_String_free(&s);
    str_String_free(&c);
    str_String_free(&h);
}

void parse_Parser_errorMsg(parse_Parser* self, const char* code, const char* m, const char* help)
{
    if (self->errored)
    {
        return;
    }
    parse_Parser_setErr(self, parse_Parser_peekTok(self, 0), code, m, help);
}

void parse_Parser_errorTok(parse_Parser* self, tok_LexTok* t, const char* code, const char* m, const char* help)
{
    if (self->errored)
    {
        return;
    }
    parse_Parser_setErr(self, t, code, m, help);
}

void parse_Parser_tokenDisplayStr(parse_Parser* self, str_String* s, tok_LexTok* t)
{
    if ((t->id == tok_TOK_EOF))
    {
        str_String_pushView(s, str_strView_fromCstr("end of file"));
    }
    else
    {
        str_String_pushView(s, str_strView_fromCstr("'"));
        str_String_pushView(s, parse_Parser_text(self, t));
        str_String_pushView(s, str_strView_fromCstr("'"));
    }
}

void parse_Parser_errExpectTok(parse_Parser* self, uint32_t want)
{
    if (self->errored)
    {
        return;
    }
    str_String s = str_String_new();
    tok_LexTok* got = parse_Parser_peekTok(self, 0);
    if ((want == tok_T_GT))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected '>'"));
    }
    else
    if ((want == tok_T_SEMI))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected ';'"));
    }
    else
    if ((want == tok_T_RPAREN))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected ')'"));
    }
    else
    if ((want == tok_T_RBRACE))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected '}'"));
    }
    else
    if ((want == tok_T_LBRACE))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected '{'"));
    }
    else
    if ((want == tok_T_LPAREN))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected '('"));
    }
    else
    if ((want == tok_T_RBRACKET))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected ']'"));
    }
    else
    if ((want == tok_T_LBRACKET))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected '['"));
    }
    else
    if ((want == tok_T_COLON))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected ':'"));
    }
    else
    if ((want == tok_T_COMMA))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected ','"));
    }
    else
    if ((want == tok_T_ASSIGN))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected '='"));
    }
    else
    if (((want == tok_TOK_IDENT) || (want == tok_T_SELF)))
    {
        str_String_pushView(&s, str_strView_fromCstr("expected a name"));
    }
    else
    {
        str_String_pushView(&s, str_strView_fromCstr("expected token"));
    }
    str_String_pushView(&s, str_strView_fromCstr(", found "));
    parse_Parser_tokenDisplayStr(self, (&s), got);
    str_String c = str_String_new();
    str_String_pushView(&c, str_strView_fromCstr("SYN-1002"));
    str_String h = str_String_new();
    str_String_pushView(&h, str_strView_fromCstr("a closing delimiter or required token is missing; check the surrounding grammar"));
    parse_Parser_setErrAt(self, got, (&s), (&c), (&h));
    str_String_free(&s);
    str_String_free(&c);
    str_String_free(&h);
}

bool parse_Parser_expect(parse_Parser* self, uint32_t t)
{
    if (parse_Parser_check(self, t))
    {
        parse_Parser_advance(self);
        return true;
    }
    parse_Parser_errExpectTok(self, t);
    return false;
}

str_strView parse_Parser_expectIdent(parse_Parser* self)
{
    tok_LexTok* t = parse_Parser_peekTok(self, 0);
    if ((parse_Parser_isNameTok(self, t) || (t->id == tok_T_SELF)))
    {
        parse_Parser_advance(self);
        return parse_Parser_text(self, t);
    }
    parse_Parser_errExpectTok(self, tok_TOK_IDENT);
    return str_strView_empty();
}

str_strView parse_Parser_expectString(parse_Parser* self)
{
    tok_LexTok* t = parse_Parser_peekTok(self, 0);
    if ((t->id == tok_TOK_STR))
    {
        parse_Parser_advance(self);
        if ((t->len >= 2))
        {
            return str_strView_fromParts(((self->source.ptr + t->start) + 1), (t->len - 2));
        }
        return str_strView_fromParts((self->source.ptr + t->start), t->len);
    }
    parse_Parser_errExpectTok(self, t->id);
    return str_strView_empty();
}

void parse_Parser_skipSemicolons(parse_Parser* self)
{
    while (parse_Parser_check(self, tok_T_SEMI))
    {
        parse_Parser_advance(self);
    }
}

parse_Mark parse_Parser_mark(parse_Parser* self)
{
    parse_Mark m;
    (m.pos = self->pos);
    (m.nctx = self->nctx);
    (m.wasErr = self->errored);
    return m;
}

void parse_Parser_rewind(parse_Parser* self, parse_Mark m)
{
    (self->pos = m.pos);
    (self->nctx = m.nctx);
    if ((!m.wasErr))
    {
        (self->errored = false);
    }
}

void parse_Parser_skipAttrBrackets(parse_Parser* self)
{
    while (((!parse_Parser_check(self, tok_T_RBRACKET)) && (!parse_Parser_check(self, tok_TOK_EOF))))
    {
        parse_Parser_advance(self);
    }
    if (parse_Parser_check(self, tok_T_RBRACKET))
    {
        parse_Parser_advance(self);
    }
    if (parse_Parser_check(self, tok_T_RBRACKET))
    {
        parse_Parser_advance(self);
    }
}

void parse_Parser_captureFileAttr(parse_Parser* self)
{
    if ((!self->recordAttrs))
    {
        return;
    }
    if ((self->nfattrs >= self->fattrsCap))
    {
        uint32_t nc = (self->fattrsCap ? (self->fattrsCap * 2) : 8);
        str_strView* na = mman_alloc_str_strView(nc);
        for (uint32_t i = 0; (i < self->nfattrs); (i++))
        {
            (na[i] = self->fattrs[i]);
        }
        if (((self->fattrs != NULL) && (self->fattrsCap > 0)))
        {
            mman_dealloc_str_strView(self->fattrs);
        }
        (self->fattrs = na);
        (self->fattrsCap = nc);
    }
    (self->fattrs[(self->nfattrs++)] = parse_Parser_text(self, parse_Parser_peekTok(self, 0)));
}

void parse_Parser_skipFileAttrs(parse_Parser* self)
{
    while (true)
    {
        if (parse_Parser_check(self, tok_T_AT))
        {
            parse_Parser_advance(self);
            if ((parse_Parser_check(self, tok_T_LBRACKET) && (parse_Parser_peekTok(self, 1)->id == tok_T_LBRACKET)))
            {
                parse_Parser_advance(self);
                parse_Parser_advance(self);
                if (parse_Parser_isNameTok(self, parse_Parser_peekTok(self, 0)))
                {
                    parse_Parser_captureFileAttr(self);
                }
                parse_Parser_skipAttrBrackets(self);
            }
            else
            {
                parse_Parser_advance(self);
            }
            continue;
        }
        break;
    }
}

bool parse_Parser_hasAttr(parse_Parser* self, const char* name)
{
    for (uint32_t i = 0; (i < self->nattrs); (i++))
    {
        if (parse_vEq(self->attrs[i], name))
        {
            return true;
        }
    }
    return false;
}

void parse_Parser_parseAttachedAttrs(parse_Parser* self)
{
    while ((parse_Parser_check(self, tok_T_LBRACKET) && (parse_Parser_peekTok(self, 1)->id == tok_T_LBRACKET)))
    {
        parse_Parser_advance(self);
        parse_Parser_advance(self);
        while (((!parse_Parser_check(self, tok_T_RBRACKET)) && (!parse_Parser_check(self, tok_TOK_EOF))))
        {
            if (parse_Parser_check(self, tok_T_COMMA))
            {
                parse_Parser_advance(self);
                continue;
            }
            if ((parse_Parser_check(self, tok_TOK_IDENT) || parse_Parser_check(self, tok_T_SELF)))
            {
                if ((self->nattrs < 8))
                {
                    (self->attrs[(self->nattrs++)] = parse_Parser_text(self, parse_Parser_peekTok(self, 0)));
                }
                parse_Parser_advance(self);
            }
            else
            {
                parse_Parser_advance(self);
            }
        }
        parse_Parser_skipAttrBrackets(self);
    }
    while ((parse_Parser_check(self, tok_T_AT) && (parse_Parser_peekTok(self, 1)->id == tok_T_LBRACKET)))
    {
        parse_Parser_advance(self);
        parse_Parser_advance(self);
        while (((!parse_Parser_check(self, tok_T_RBRACKET)) && (!parse_Parser_check(self, tok_TOK_EOF))))
        {
            if (parse_Parser_check(self, tok_T_COMMA))
            {
                parse_Parser_advance(self);
                continue;
            }
            if ((parse_Parser_check(self, tok_TOK_IDENT) || parse_Parser_check(self, tok_T_SELF)))
            {
                if ((self->nattrs < 8))
                {
                    (self->attrs[(self->nattrs++)] = parse_Parser_text(self, parse_Parser_peekTok(self, 0)));
                }
                parse_Parser_advance(self);
            }
            else
            {
                parse_Parser_advance(self);
            }
        }
        parse_Parser_skipAttrBrackets(self);
    }
}

void parse_Parser_growPtrArr(parse_Parser* self, void*** arr, uint32_t* n, uint32_t* cap)
{
    if (((*n) < (*cap)))
    {
        return;
    }
    uint32_t nc = ((*cap) ? ((*cap) * 2) : 8);
    void** na = mman_alloc_void_ptr(nc);
    for (uint32_t i = 0; (i < (*n)); (i++))
    {
        (na[i] = ((*arr))[i]);
    }
    if ((*arr))
    {
        mman_dealloc_void_ptr((*arr));
    }
    ((*arr) = na);
    ((*cap) = nc);
}

