void parse_Parser_parseParamList(parse_Parser* self, ast_Param** arr, uint32_t* n, uint32_t* cap, bool* variadic)
{
    if ((parse_Parser_check(self, tok_T_RPAREN) || parse_Parser_check(self, tok_T_SEMI)))
    {
        return;
    }
    if (parse_Parser_check(self, tok_T_ELLIPSIS))
    {
        parse_Parser_advance(self);
        ((*variadic) = true);
        return;
    }
    while (true)
    {
        if (parse_Parser_hazardStop(self))
        {
            break;
        }
        bool isNonull = false;
        if ((parse_Parser_check(self, tok_T_LBRACKET) && (parse_Parser_peekTok(self, 1)->id == tok_T_LBRACKET)))
        {
            parse_Parser_parseAttachedAttrs(self);
            if (parse_Parser_hasAttr(self, "nonull"))
            {
                (isNonull = true);
            }
            (self->nattrs = 0);
        }
        ast_TypeExpr* pt = NULL;
        str_strView pn = str_strView_empty();
        bool named = false;
        if (parse_Parser_check(self, tok_T_SELF))
        {
            parse_Mark saved = parse_Parser_mark(self);
            parse_Parser_advance(self);
            if (parse_Parser_check(self, tok_T_COLON))
            {
                parse_Parser_advance(self);
                (pt = parse_Parser_parseType(self));
                if ((parse_Parser_isNameTok(self, parse_Parser_peekTok(self, 0)) || parse_Parser_check(self, tok_T_SELF)))
                {
                    (pn = parse_Parser_text(self, parse_Parser_peekTok(self, 0)));
                    parse_Parser_advance(self);
                    (named = true);
                }
                else
                {
                    (pn = str_strView_fromCstr("self"));
                }
            }
            else
            {
                parse_Parser_rewind(self, saved);
                (pt = parse_Parser_parseType(self));
                if ((pt == NULL))
                {
                    parse_Parser_errExpectTok(self, tok_TOK_IDENT);
                    return;
                }
                if ((parse_Parser_isNameTok(self, parse_Parser_peekTok(self, 0)) || parse_Parser_check(self, tok_T_SELF)))
                {
                    (pn = parse_Parser_text(self, parse_Parser_peekTok(self, 0)));
                    parse_Parser_advance(self);
                }
                else
                {
                    (pn = str_strView_fromCstr("self"));
                }
            }
        }
        else
        {
            (pt = parse_Parser_parseType(self));
            if ((pt == NULL))
            {
                parse_Parser_errExpectTok(self, tok_TOK_IDENT);
                return;
            }
            if (parse_Parser_check(self, tok_T_ELLIPSIS))
            {
                parse_Parser_advance(self);
                ((*variadic) = true);
                if ((parse_Parser_isNameTok(self, parse_Parser_peekTok(self, 0)) || parse_Parser_check(self, tok_T_SELF)))
                {
                    (pn = parse_Parser_text(self, parse_Parser_peekTok(self, 0)));
                    parse_Parser_advance(self);
                    (named = true);
                }
            }
            else
            if ((parse_Parser_isNameTok(self, parse_Parser_peekTok(self, 0)) || parse_Parser_check(self, tok_T_SELF)))
            {
                (pn = parse_Parser_text(self, parse_Parser_peekTok(self, 0)));
                parse_Parser_advance(self);
                (named = true);
            }
        }
        ast_Param p;
        (p.name = pn);
        (p.type = pt);
        (p.nonull = isNonull);
        parse_Parser_growParamU(self, arr, n, cap);
        (((*arr))[(*n)].name = p.name);
        (((*arr))[(*n)].type = p.type);
        (((*arr))[(*n)].nonull = p.nonull);
        ((*n) = ((*n) + 1));
        if ((!parse_Parser_check(self, tok_T_COMMA)))
        {
            break;
        }
        parse_Parser_advance(self);
        if (parse_Parser_check(self, tok_T_ELLIPSIS))
        {
            parse_Parser_advance(self);
            ((*variadic) = true);
            break;
        }
        if (parse_Parser_check(self, tok_T_RPAREN))
        {
            break;
        }
    }
}

bool parse_Parser_hazardStop(parse_Parser* self)
{
    return parse_Parser_check(self, tok_TOK_EOF);
}

bool parse_Parser_stallTickTag(parse_Parser* self, const char* tag)
{
    if ((self->pos == self->lastStallPos))
    {
        (self->stallCount++);
        if ((self->stallCount > 100000))
        {
            tok_LexTok* t = parse_Parser_peekTok(self, 0);
            str_String s = str_String_new();
            str_String_pushView(&s, str_strView_fromCstr("parser stall("));
            str_String_pushView(&s, str_strView_fromCstr(tag));
            str_String_pushView(&s, str_strView_fromCstr(") at token: "));
            parse_Parser_tokenDisplayStr(self, (&s), t);
            str_String_pushView(&s, str_strView_fromCstr(" pos="));
            str_String_pushView(&s, str_strView_fromParts((const char*)((self->source.ptr + t->start)), 16));
            (self->errLine = t->row);
            parse_Parser_setErr(self, t, "SYN-1999", "parser stall detected", "the parser made no forward progress; the preceding construct is likely grammatically invalid");
            str_String_free(&s);
            return true;
        }
    }
    else
    {
        (self->lastStallPos = self->pos);
        (self->stallCount = 0);
    }
    return false;
}

