bool parse_Parser_ltIsGeneric(parse_Parser* self)
{
    int32_t i = ((int32_t)self->pos + 1);
    int32_t depth = 1;
    while ((i < (int32_t)self->n))
    {
        uint32_t id = self->toks[i].id;
        if ((id == tok_T_LT))
        {
            (depth++);
        }
        else
        if ((id == tok_T_GT))
        {
            (depth--);
            if ((depth == 0))
            {
                uint32_t nxt = (((i + 1) < (int32_t)self->n) ? self->toks[(i + 1)].id : tok_TOK_EOF);
                if (((((((((((nxt == tok_T_LPAREN) || (nxt == tok_T_DOT)) || (nxt == tok_T_COLON_COLON)) || (nxt == tok_T_SEMI)) || (nxt == tok_T_COMMA)) || (nxt == tok_T_RPAREN)) || (nxt == tok_T_RBRACKET)) || (nxt == tok_T_ASSIGN)) || (nxt == tok_T_LBRACE)) || (nxt == tok_T_LBRACKET)))
                {
                    return true;
                }
                return false;
            }
            if ((depth < 0))
            {
                return false;
            }
        }
        else
        if ((id == tok_T_SHR))
        {
            (depth -= 2);
            if ((depth == 0))
            {
                uint32_t nxt = (((i + 1) < (int32_t)self->n) ? self->toks[(i + 1)].id : tok_TOK_EOF);
                if (((((((((((nxt == tok_T_LPAREN) || (nxt == tok_T_DOT)) || (nxt == tok_T_COLON_COLON)) || (nxt == tok_T_SEMI)) || (nxt == tok_T_COMMA)) || (nxt == tok_T_RPAREN)) || (nxt == tok_T_RBRACKET)) || (nxt == tok_T_ASSIGN)) || (nxt == tok_T_LBRACE)) || (nxt == tok_T_LBRACKET)))
                {
                    return true;
                }
                return false;
            }
            if ((depth < 0))
            {
                return false;
            }
        }
        else
        if (((((id == tok_T_SEMI) || (id == tok_T_LPAREN)) || (id == tok_T_RBRACE)) || (id == tok_TOK_EOF)))
        {
            return false;
        }
        (i++);
    }
    return false;
}

