void check_Check_declareSym(check_Check* self, scopes_Scope* top, ast_Decl* d, uint32_t kind, types_CType* ct)
{
    if (((((kind == scopes_SYM_ENUM) || (kind == scopes_SYM_STRUCT)) || (kind == scopes_SYM_TYPEDEF)) || (kind == scopes_SYM_DISTINCT)))
    {
        scopes_Sym* existing = scopes_scopeLookup(top, d->name);
        if (((existing != NULL) && (existing->kind == kind)))
        {
            return;
        }
    }
    scopes_Sym* s = scopes_symNew(d->name, kind, d, d->line, d->col);
    (s->type = ct);
    if ((!scopes_scopeDeclare(top, s)))
    {
        check_Check_errDecl(self, d, str_strView_fromCstr("TC-REDECL"), str_strView_fromCstr("redeclaration of '"), str_strView_empty());
        str_String msg = str_String_new();
        str_String_pushView(&msg, d->name);
        str_String_pushChar(&msg, '\'');
        check_Check_errDecl(self, d, str_strView_fromCstr("TC-REDECL"), str_strView_fromParts(msg.ptr, msg.len), str_strView_empty());
        str_String_free(&msg);
    }
}

bool check_Check_vEqCI(check_Check* self, str_strView a, str_strView b)
{
    if ((a.len != b.len))
    {
        return false;
    }
    for (uint32_t i = 0; (i < a.len); (i++))
    {
        char ca = a.ptr[i];
        if (((ca >= 'A') && (ca <= 'Z')))
        {
            (ca = (char)(((ca - 'A') + 'a')));
        }
        char cb = b.ptr[i];
        if (((cb >= 'A') && (cb <= 'Z')))
        {
            (cb = (char)(((cb - 'A') + 'a')));
        }
        if ((ca != cb))
        {
            return false;
        }
    }
    return true;
}

bool check_Check_vEqSV(check_Check* self, str_strView a, str_strView b)
{
    if ((a.len != b.len))
    {
        return false;
    }
    for (uint32_t i = 0; (i < a.len); (i++))
    {
        if ((a.ptr[i] != b.ptr[i]))
        {
            return false;
        }
    }
    return true;
}

str_strView check_Check_flagValue(check_Check* self, str_strView name)
{
    for (uint32_t i = 0; (i < self->nflags); (i++))
    {
        if (check_Check_vEqCI(self, self->flagNames[i], name))
        {
            return self->flagVals[i];
        }
    }
    return str_strView_empty();
}

