void scopes_modsAdd(scopes_ModuleTable* m, str_strView alias, str_strView path)
{
    uint32_t nc = (m->n + 1);
    str_strView* na = mman_alloc_str_strView(nc);
    str_strView* np = mman_alloc_str_strView(nc);
    char* acopy = (char*)mman_alloc_u8((alias.len ? alias.len : 1));
    memcpy(acopy, alias.ptr, alias.len);
    char* pcopy = (char*)mman_alloc_u8((path.len ? path.len : 1));
    memcpy(pcopy, path.ptr, path.len);
    for (uint32_t i = 0; (i < m->n); (i++))
    {
        (na[i] = m->aliases[i]);
        (np[i] = m->paths[i]);
    }
    (na[m->n] = str_strView_fromParts(acopy, alias.len));
    (np[m->n] = str_strView_fromParts(pcopy, path.len));
    if (m->aliases)
    {
        mman_dealloc_str_strView(m->aliases);
    }
    if (m->paths)
    {
        mman_dealloc_str_strView(m->paths);
    }
    (m->aliases = na);
    (m->paths = np);
    (m->n = nc);
}

