ast_Decl* scopes_findMethod(ast_Decl* structDecl, ast_Program* prog, str_strView mname)
{
    if ((structDecl != NULL))
    {
        for (uint32_t i = 0; (i < structDecl->ndecls); (i++))
        {
            ast_Decl* m = structDecl->decls[i];
            if (((m != NULL) && scopes_sEq(m->name, mname)))
            {
                return m;
            }
        }
    }
    for (uint32_t i = 0; ((prog != NULL) && (i < prog->ndecls)); (i++))
    {
        ast_Decl* d = prog->decls[i];
        if ((((d->kind == ast_DT_METHODBLOCK) && (d->structName.len > 0)) && scopes_sEq(d->structName, structDecl->name)))
        {
            for (uint32_t j = 0; (j < d->ndecls); (j++))
            {
                ast_Decl* m = d->decls[j];
                if (((m != NULL) && scopes_sEq(m->name, mname)))
                {
                    return m;
                }
            }
        }
    }
    return NULL;
}

