bool ceval_strEqOp(str_strView op, const char* b)
{
    uint64_t n = 0;
    while ((b[n] != 0))
    {
        (n++);
    }
    if ((op.len != n))
    {
        return false;
    }
    return (memcmp((const void*)op.ptr, (const void*)b, n) == 0);
}

