            (vfg.prog = prog);
            (vfg.ld = ld);
            types_CType* vct = (d->type ? scopes_resolveTypeExpr(d->type, top, mods, NULL, 0) : NULL);
            ir_types_IrType* vt = (vct ? emitir_mapCType((&vfg), vct) : ir_types_IrContext_tyInt(ctx, 64));
            ir_types_IrGlobal* vg = ir_types_IrContext_createGlobal(ctx, vb, vt, false, true, NULL, 0);
            ir_types_IrModule_addGlobal(irMod, vg);
