void emitir_emitIR(ast_Program* prog, scopes_Scope* top, scopes_ModuleTable* mods, loader_Loader* ld, str_strView path, uint32_t optLevel, bool debug)
{
    str_String opath = str_String_new();
    uint32_t lastDot = 0;
    bool dot = false;
    for (uint32_t k = 0; (k < path.len); (k++))
    {
        if ((path.ptr[k] == (uint8_t)'.'))
        {
            (lastDot = k);
            (dot = true);
        }
    }
    if (dot)
    {
        str_String_pushView(&opath, str_strView_fromParts(path.ptr, lastDot));
    }
    else
    {
        str_String_pushView(&opath, path);
    }
    str_String_pushCstr(&opath, ".wir");
    ir_types_IrContext* ctx = NULL;
    ir_types_IrModule* irMod = emitir_buildModule(prog, top, mods, ld, path, optLevel, debug, (&ctx));
    void* f = fopen(str_String_asCstr(&opath), (const uint8_t*)"wb");
    if ((f != NULL))
    {
        emitir_dumpIR(irMod, f);
        fclose(f);
        write(1, (const uint8_t*)"wrote ", 6);
        write(1, (const uint8_t*)str_String_asCstr(&opath), opath.len);
        write(1, (const uint8_t*)"\n", 1);
    }
    else
    {
        write(2, (const uint8_t*)"coralc: cannot write wallvm ir file\n", 28);
    }
    str_String_free(&opath);
}

wallvm_PassPipeline wallvm_PassPipeline_new()
{
    wallvm_PassPipeline p;
    (p.passes = NULL);
    (p.names = NULL);
    (p.count = 0);
    (p.capacity = 0);
    return p;
}

void wallvm_PassPipeline_add(wallvm_PassPipeline* self, wallvm_PassFn fn, const char* name)
{
    if ((self->count >= self->capacity))
    {
        uint32_t nc = (self->capacity ? (self->capacity * 2) : 8);
        wallvm_PassFn* np = mman_alloc_wallvm_PassFn_ptr(nc);
        char** nn = mman_alloc_char_ptr(nc);
        for (uint32_t i = 0; (i < self->count); (i++))
        {
            (np[i] = self->passes[i]);
            (nn[i] = self->names[i]);
        }
        if (self->passes)
        {
            mman_dealloc_wallvm_PassFn_ptr(self->passes);
        }
        if (self->names)
        {
            mman_dealloc_char_ptr(self->names);
        }
        (self->passes = np);
        (self->names = nn);
        (self->capacity = nc);
    }
    (self->passes[self->count] = fn);
    (self->names[self->count] = name);
    (self->count++);
}

void wallvm_PassPipeline_clear(wallvm_PassPipeline* self)
{
    if (self->passes)
    {
        mman_dealloc_wallvm_PassFn_ptr(self->passes);
    }
    if (self->names)
    {
        mman_dealloc_char_ptr(self->names);
    }
    (self->passes = NULL);
    (self->names = NULL);
    (self->count = 0);
    (self->capacity = 0);
}

bool wallvm_PassPipeline_runOnFunc(wallvm_PassPipeline* self, ir_types_IrFunc* func, void* ctx)
{
    bool changed = false;
    for (uint32_t i = 0; (i < self->count); (i++))
    {
        if (self->passes[i](func, ctx))
        {
            (changed = true);
        }
    }
    return changed;
}

