void ir_types_IrValue_addUser(ir_types_IrValue* self, ir_types_IrInst* inst)
{
    if ((self->nusers >= self->capUsers))
    {
        uint32_t newCap = (self->capUsers ? (self->capUsers * 2) : 4);
        ir_types_IrInst** newUsers = mman_alloc_ir_types_IrInst_ptr(newCap);
        if (self->users)
        {
            mman_copy_ir_types_IrInst_ptr(newUsers, self->users, self->nusers);
            mman_dealloc_ir_types_IrInst_ptr(self->users);
        }
        (self->users = newUsers);
        (self->capUsers = newCap);
    }
    (self->users[(self->nusers++)] = inst);
}

void ir_types_IrValue_removeUser(ir_types_IrValue* self, ir_types_IrInst* inst)
{
    for (uint32_t i = 0; (i < self->nusers); (i++))
    {
        if ((self->users[i] == inst))
        {
            (self->users[i] = self->users[(--self->nusers)]);
            return;
        }
    }
}

void ir_types_IrValue_replaceAllUses(ir_types_IrValue* self, ir_types_IrValue* newVal)
{
    if ((self == newVal))
    {
        return;
    }
    for (uint32_t ui = 0; (ui < self->nusers); (ui++))
    {
        ir_types_IrInst* user = self->users[ui];
        for (uint32_t j = 0; (j < user->nops); (j++))
        {
            if ((user->ops[j] == self))
            {
                (user->ops[j] = newVal);
            }
        }
        ir_types_IrValue_addUser(newVal, user);
    }
    (self->nusers = 0);
}

