void ir_types_IrInst_setDebugLoc(ir_types_IrInst* self, const char* file, uint32_t line, uint32_t col)
{
    if ((!file))
    {
        return;
    }
    uint32_t len = 0;
    while (file[len])
    {
        (len++);
    }
    char* copy = mman_alloc_char((len + 1));
    for (uint32_t i = 0; (i < len); (i++))
    {
        (copy[i] = file[i]);
    }
    (copy[len] = 0);
    (self->debugLoc.file = copy);
    (self->debugLoc.line = line);
    (self->debugLoc.col = col);
}

void ir_types_IrInst_addVarDebug(ir_types_IrInst* self, const char* name, ir_types_IrType* ty, uint32_t line, uint32_t col, uint32_t argIdx)
{
    if ((self->nvarDbg >= self->capVarDbg))
    {
        uint32_t nc = (self->capVarDbg ? (self->capVarDbg * 2) : 4);
        ir_types_IrVarDebugInfo* nd = mman_alloc_ir_types_IrVarDebugInfo(nc);
        if (self->varDbg)
        {
            mman_copy_ir_types_IrVarDebugInfo(nd, self->varDbg, self->nvarDbg);
            mman_dealloc_ir_types_IrVarDebugInfo(self->varDbg);
        }
        (self->varDbg = nd);
        (self->capVarDbg = nc);
    }
    uint32_t nl = 0;
    while (name[nl])
    {
        (nl++);
    }
    char* nc = mman_alloc_char((nl + 1));
    for (uint32_t i = 0; (i < nl); (i++))
    {
        (nc[i] = name[i]);
    }
    (nc[nl] = 0);
    (self->varDbg[(self->nvarDbg++)] = (ir_types_IrVarDebugInfo){nc, ty, line, col, argIdx});
}

void ir_types_IrInst_erase(ir_types_IrInst* self)
{
    if (self->parent)
    {
        for (uint32_t i = 0; (i < self->parent->ninsts); (i++))
        {
            if ((self->parent->insts[i] == self))
            {
                for (uint32_t j = i; (j < (self->parent->ninsts - 1)); (j++))
                {
                    (self->parent->insts[j] = self->parent->insts[(j + 1)]);
                }
                (self->parent->ninsts--);
                break;
            }
        }
    }
    for (uint32_t i = 0; (i < self->nops); (i++))
    {
        if (self->ops[i])
        {
            ir_types_IrValue_removeUser(self->ops[i], self);
        }
    }
    if ((self->capOps > 0))
    {
        mman_dealloc_ir_types_IrValue_ptr(self->ops);
    }
    if ((self->base.capUsers > 0))
    {
        mman_dealloc_ir_types_IrInst_ptr(self->base.users);
    }
    if (self->debugLoc.file)
    {
        mman_dealloc_char(self->debugLoc.file);
    }
    if (self->varDbg)
    {
        for (uint32_t i = 0; (i < self->nvarDbg); (i++))
        {
            if (self->varDbg[i].varName)
            {
                mman_dealloc_char(self->varDbg[i].varName);
            }
        }
        mman_dealloc_ir_types_IrVarDebugInfo(self->varDbg);
    }
    mman_dealloc_ir_types_IrInst(self);
}

