bool ir_types_irTypeEqual(ir_types_IrType* a, ir_types_IrType* b)
{
    if (((!a) || (!b)))
    {
        return false;
    }
    if ((a->kind != b->kind))
    {
        return false;
    }
    switch (a->kind)
    {
        case ir_types_IrTypeKind_Void:
            return true;
        case ir_types_IrTypeKind_Int:
        case ir_types_IrTypeKind_Float:
            return (a->width == b->width);
        case ir_types_IrTypeKind_Ptr:
            return ir_types_irTypeEqual(a->elem, b->elem);
        case ir_types_IrTypeKind_Array:
            return ((a->count == b->count) && ir_types_irTypeEqual(a->elem, b->elem));
        case ir_types_IrTypeKind_Vector:
            return ((a->count == b->count) && ir_types_irTypeEqual(a->elem, b->elem));
        case ir_types_IrTypeKind_Func:
            if ((((!ir_types_irTypeEqual(a->ret, b->ret)) || (a->isVararg != b->isVararg)) || (a->nparams != b->nparams)))
            {
                return false;
            }
            for (uint32_t i = 0; (i < a->nparams); (i++))
            {
                if ((!ir_types_irTypeEqual(a->params[i], b->params[i])))
                {
                    return false;
                }
            }
            return true;
    }
    return false;
}

char* ir_types_irTypeStr(ir_types_IrType* t)
{
    if ((!t))
    {
        return "void";
    }
    switch (t->kind)
    {
        case ir_types_IrTypeKind_Void:
            return "void";
        case ir_types_IrTypeKind_Int:
            if ((t->width == 1))
            {
                return "i1";
            }
            if ((t->width == 8))
            {
                return "i8";
            }
            if ((t->width == 16))
            {
                return "i16";
            }
            if ((t->width == 32))
            {
                return "i32";
            }
            if ((t->width == 64))
            {
                return "i64";
            }
            return "iN";
        case ir_types_IrTypeKind_Float:
            return ((t->width == 64) ? "f64" : "float");
        case ir_types_IrTypeKind_Ptr:
            return "ptr";
        case ir_types_IrTypeKind_Array:
            return "array";
        case ir_types_IrTypeKind_Vector:
            return "vector";
        case ir_types_IrTypeKind_Func:
            return "func";
    }
    return "unknown";
}

