    if (((a->kind == ir_types_IrValueKind_Inst) && (b->kind == ir_types_IrValueKind_ConstInt)))
    {
        (cand = a);
    }
    else
    if (((b->kind == ir_types_IrValueKind_Inst) && (a->kind == ir_types_IrValueKind_ConstInt)))
    {
        (cand = b);
    }
