                    break;
                case ir_opcodes_IrOpcode_Gep:
                    x86_64_X86_64Codegen_emitGep(self, inst);
                    break;
                case ir_opcodes_IrOpcode_Trunc:
                case ir_opcodes_IrOpcode_Zext:
                case ir_opcodes_IrOpcode_Sext:
                case ir_opcodes_IrOpcode_FpTrunc:
                case ir_opcodes_IrOpcode_FpExt:
                case ir_opcodes_IrOpcode_FpToSi:
                case ir_opcodes_IrOpcode_SiToFp:
                case ir_opcodes_IrOpcode_FpToUi:
                case ir_opcodes_IrOpcode_UiToFp:
                case ir_opcodes_IrOpcode_Bitcast:
                    x86_64_X86_64Codegen_emitCast(self, inst);
                    break;
                case ir_opcodes_IrOpcode_ICmp:
                    if (x86_64_X86_64Codegen_icmpSkipped(self, inst))
                    {
                        break;
                    }
                    x86_64_X86_64Codegen_emitICmp(self, inst);
                    break;
                case ir_opcodes_IrOpcode_FCmp:
                    x86_64_X86_64Codegen_emitFCmp(self, inst);
                    break;
                case ir_opcodes_IrOpcode_Call:
                    x86_64_X86_64Codegen_emitCall(self, inst);
