                    break;
                case ir_opcodes_IrOpcode_Select:
                    x86_64_X86_64Codegen_emitSelect(self, inst);
                    break;
                default:
                    x86_64_X86_64Codegen_pad(self);
                    x86_64_X86_64Codegen_s(self, "; unsupported opcode: ");
                    x86_64_X86_64Codegen_s(self, ir_opcodes_irOpcodeStr(inst->opcode));
