arm64_Arm64Codegen arm64_Arm64Codegen_new(ir_types_IrContext* ctx)
{
    arm64_Arm64Codegen c;
    (c.ctx = ctx);
    (c.abi = asm_rules_aapcs64Abi());
    (c.out = NULL);
    (c.outLen = 0);
    (c.outCap = 0);
    (c.func = NULL);
    (c.frameSize = 0);
    (c.stackSlots = NULL);
    (c.stackSlotsLen = 0);
    (c.stackSlotsCap = 0);
    (c.blockLabels = NULL);
    (c.blockLabelsCap = 0);
    return c;
}

void arm64_Arm64Codegen_grow(arm64_Arm64Codegen* self, uint32_t n)
{
    if ((self->outCap >= (self->outLen + n)))
    {
        return;
    }
    uint32_t nc = (self->outCap ? (self->outCap * 2) : 4096);
    while ((nc < (self->outLen + n)))
    {
        (nc *= 2);
    }
    char* nb = mman_alloc_char(nc);
    if (self->out)
    {
        for (uint32_t i = 0; (i < self->outLen); (i++))
        {
            (nb[i] = self->out[i]);
        }
        mman_dealloc_char(self->out);
    }
    (self->out = nb);
    (self->outCap = nc);
}

void arm64_Arm64Codegen_c(arm64_Arm64Codegen* self, char ch)
{
    arm64_Arm64Codegen_grow(self, 1);
    (self->out[(self->outLen++)] = ch);
}

void arm64_Arm64Codegen_s(arm64_Arm64Codegen* self, const char* p)
{
    if ((!p))
    {
        return;
    }
    uint32_t l = 0;
    while (p[l])
    {
        (l++);
    }
    if ((!l))
    {
        return;
    }
    arm64_Arm64Codegen_grow(self, l);
    for (uint32_t i = 0; (i < l); (i++))
    {
        (self->out[(self->outLen++)] = p[i]);
    }
}

void arm64_Arm64Codegen_u(arm64_Arm64Codegen* self, uint64_t v)
{
    if ((v == 0))
    {
        arm64_Arm64Codegen_c(self, '0');
        return;
    }
    char b[24];
    uint32_t p = 24;
    while (v)
    {
        (b[(--p)] = (char)(('0' + ((v % 10)))));
        (v /= 10);
    }
    while ((p < 24))
    {
        arm64_Arm64Codegen_c(self, b[(p++)]);
    }
}

void arm64_Arm64Codegen_pad(arm64_Arm64Codegen* self)
{
    arm64_Arm64Codegen_c(self, ' ');
    arm64_Arm64Codegen_c(self, ' ');
    arm64_Arm64Codegen_c(self, ' ');
    arm64_Arm64Codegen_c(self, ' ');
}

