            riscv_RiscvCodegen_inst3(self, "xori", "a0", "a0", "1");
            break;
        case ir_opcodes_IrICmpPred_Sgt:
            riscv_RiscvCodegen_inst3(self, "slt", "a0", "a1", "a0");
            break;
        case ir_opcodes_IrICmpPred_Sge:
            riscv_RiscvCodegen_inst3(self, "slt", "a0", "a0", "a1");
            riscv_RiscvCodegen_inst3(self, "xori", "a0", "a0", "1");
            break;
        case ir_opcodes_IrICmpPred_Ult:
            riscv_RiscvCodegen_inst3(self, "sltu", "a0", "a0", "a1");
            break;
        case ir_opcodes_IrICmpPred_Ule:
            riscv_RiscvCodegen_inst3(self, "sltu", "a0", "a1", "a0");
            riscv_RiscvCodegen_inst3(self, "xori", "a0", "a0", "1");
