uint32_t ppc64_Ppc64Codegen_slot(ppc64_Ppc64Codegen* self, ir_types_IrValue* v)
{
    if ((!v))
    {
        return 0;
    }
    uint32_t id = v->id;
    if ((id >= self->stackSlotsCap))
    {
        ppc64_Ppc64Codegen_ensureSlots(self, id);
    }
    if ((self->stackSlots[id] == 0))
    {
        (self->stackSlots[id] = self->frameSize);
        (self->frameSize += 8);
    }
    return self->stackSlots[id];
}

bool ppc64_Ppc64Codegen_isConst(ppc64_Ppc64Codegen* self, ir_types_IrValue* v)
{
    if ((!v))
    {
        return true;
    }
    ir_types_IrValueKind k = v->kind;
    return ((k == ir_types_IrValueKind_ConstInt) || (k == ir_types_IrValueKind_ConstFloat));
}

