                case ir_opcodes_IrOpcode_Neg:
                    ppc64_Ppc64Codegen_emitUnary(self, inst, "neg");
                    break;
                case ir_opcodes_IrOpcode_Not:
                    ppc64_Ppc64Codegen_emitUnary(self, inst, "nor");
                    break;
                case ir_opcodes_IrOpcode_Add:
                    ppc64_Ppc64Codegen_emitArith(self, inst, "add");
                    break;
                case ir_opcodes_IrOpcode_Sub:
                    ppc64_Ppc64Codegen_emitArith(self, inst, "subf");
                    break;
                case ir_opcodes_IrOpcode_Mul:
                    ppc64_Ppc64Codegen_emitArith(self, inst, "mulld");
                    break;
                case ir_opcodes_IrOpcode_SDiv:
                    ppc64_Ppc64Codegen_emitDivRem(self, inst, "divd", true, false);
                    break;
                case ir_opcodes_IrOpcode_UDiv:
                    ppc64_Ppc64Codegen_emitDivRem(self, inst, "divdu", false, false);
                    break;
                case ir_opcodes_IrOpcode_SRem:
                    ppc64_Ppc64Codegen_emitDivRem(self, inst, "divd", true, true);
                    break;
                case ir_opcodes_IrOpcode_URem:
                    ppc64_Ppc64Codegen_emitDivRem(self, inst, "divdu", false, true);
                    break;
                case ir_opcodes_IrOpcode_And:
                    ppc64_Ppc64Codegen_emitArith(self, inst, "and");
                    break;
                case ir_opcodes_IrOpcode_Or:
                    ppc64_Ppc64Codegen_emitArith(self, inst, "or");
                    break;
                case ir_opcodes_IrOpcode_Xor:
