void mips_MipsCodegen_emitSelect(mips_MipsCodegen* self, ir_types_IrInst* inst)
{
    ir_types_IrValue* cond = ((inst->nops > 0) ? inst->ops[0] : NULL);
    ir_types_IrValue* tval = ((inst->nops > 1) ? inst->ops[1] : NULL);
    ir_types_IrValue* fval = ((inst->nops > 2) ? inst->ops[2] : NULL);
    ir_types_IrValue* res = (&inst->base);
    mips_MipsCodegen_loadArith(self, fval, "$t0");
    mips_MipsCodegen_loadArith(self, tval, "$t1");
    mips_MipsCodegen_loadArith(self, cond, "$t2");
    mips_MipsCodegen_inst2(self, "beqz", "$t2", ".Lsel");
    mips_MipsCodegen_inst2(self, "move", "$t0", "$t1");
    mips_MipsCodegen_emitLabel(self, ".Lsel");
    mips_MipsCodegen_store(self, res, "$t0");
}

