                        ir_types_IrValue* cond = ((inst->nops > 0) ? inst->ops[0] : NULL);
                        ir_types_IrValue* tv = ((inst->nops > 1) ? inst->ops[1] : NULL);
                        ir_types_IrValue* ev = ((inst->nops > 2) ? inst->ops[2] : NULL);
                        uint32_t tbi = (tv ? sparc64_Sparc64Codegen_resolveBlock(self, tv) : (~0u));
                        uint32_t ebi = (ev ? sparc64_Sparc64Codegen_resolveBlock(self, ev) : (~0u));
                        sparc64_Sparc64Codegen_emitPhiEdges(self, blk, tv);
